// 判定対象の文の抽出: コードのコメント・Markdown の本文
//   要否の判断は人・AI、書式の確定はここ
// コメント = 行頭から始まるもの（`//`・`#`・`/* */`・`{/* */}`・`<!-- -->`）
//   行の途中から始まるコメントは文字列中の `//`・`/*`（URL・glob）と区別不可 → 行末コメントはスキーマのファイルのみ対象

// `#` のコメントの拡張子（ほかは `//`）
const HASH = /\.(tf|py|sh|rb|ya?ml|toml)$/;
export type CommentKind = 'slash' | 'hash';
export const commentKind = (file: string): CommentKind => (HASH.test(file) ? 'hash' : 'slash');

// 生成物: 先頭10行に生成を示す慣習の表記（Wrangler・Payload・Go の `Code generated ... DO NOT EDIT.` など）
//   書き手が修正する文ではない → 検査の対象外
const GENERATED = /generated by|automatically generated|auto-generated|code generated|@generated|do not (edit|modify)/i;
export const isGenerated = (source: string) => GENERATED.test(source.split(/\r?\n/, 10).join('\n'));

// `start`・`end` = 行内の文の範囲（自動修正で置換）
export type Span = { line: number; start: number; end: number; text: string };

const span = (line: number, raw: string, start: number, end = raw.length): Span | undefined => {
  const part = raw.slice(start, end);
  const s = start + part.match(/^\s*/)![0].length;
  const e = Math.max(s, end - part.match(/\s*$/)![0].length);
  return e > s ? { line, start: s, end: e, text: raw.slice(s, e) } : undefined;
};

export function commentTexts(source: string, kind: CommentKind): Span[] {
  const out: Span[] = [];
  const push = (s: Span | undefined) => void (s && out.push(s));
  // 複数行のコメントの終端（`*/`・`-->`）
  //   JSDoc の `@example` とコードブロックの中は対象外
  let close = '';
  let example = false;
  let fence = false;
  // タグの行（`@param` など）は `@example` の終了だけ判定
  const body = (line: number, raw: string, start: number, end: number) => {
    const text = raw.slice(start, end).trim();
    if (/^(```|~~~)/.test(text)) fence = !fence;
    else if (text.startsWith('@')) example = text.startsWith('@example');
    else if (!fence && !example) push(span(line, raw, start, end));
  };
  source.split(/\r?\n/).forEach((raw, i) => {
    const line = i + 1;
    if (close) {
      const at = raw.indexOf(close);
      // 行頭の `*`（JSDoc の継続行）は除外
      const star = close === '*/' ? (raw.match(/^\s*\*(?!\/)/)?.[0].length ?? 0) : 0;
      body(line, raw, star, at === -1 ? raw.length : at);
      if (at !== -1) close = '';
      return;
    }
    if (i === 0 && raw.startsWith('#!')) return;
    const comment = raw.match(kind === 'hash' ? /^\s*(?:#|\/\/)/ : /^\s*\/\//);
    if (comment) return push(span(line, raw, comment[0].length));
    const html = raw.match(/^\s*<!--/);
    const block = html ?? raw.match(/^\s*\{?\s*\/\*+!?/);
    if (!block) return;
    const end = html ? '-->' : '*/';
    const at = raw.indexOf(end, block[0].length);
    example = false;
    fence = false;
    body(line, raw, block[0].length, at === -1 ? raw.length : at);
    if (at === -1) close = end;
  });
  return out;
}

// 文の途中の改行: 同じ字下げで続く2行のうち、前の行の末尾が読点・助詞、または次の行の先頭が助詞・読点
//   検出の対象: 幅の調整を目的とする折り返し → 1行1文に分割・箇条書きに変更
//   対象外: 箇条書きの行・字下げの深い補足の行・末尾が名詞の語（こと・まで・ごと）
const WRAP_END = /(、|(?<!ま)で|(?<![こご])と|[はがをにへやも])$/;
const WRAP_START = /^[をにがはでとへや、]/;
export function wrappedLines(spans: Span[]): number[] {
  const out: number[] = [];
  for (const [i, a] of spans.entries()) {
    const b = spans[i + 1];
    if (!b || b.line !== a.line + 1 || b.start !== a.start || /^(- |\d+\. )/.test(b.text)) continue;
    if (WRAP_END.test(a.text.replace(/`[^`]*`/g, 'x')) || WRAP_START.test(b.text)) out.push(a.line);
  }
  return out;
}

// フィールドの行（末尾が `,`・`;`）と行末コメント
const FIELD = /^(\s*[^\s/].*?[,;])(?:\s+\/\/ (.*))?$/;
export function trailingComment(line: string): { code: string; text?: string } | undefined {
  const m = line.match(FIELD);
  return m ? { code: m[1]!, ...(m[2] !== undefined ? { text: m[2] } : {}) } : undefined;
}

// 連続するフィールドの行を1ブロックとし、行末コメントの開始位置をブロック内の最長のコードに統一
export function alignTrailing(lines: string[], fix: (text: string) => string = (t) => t): string[] {
  const out = [...lines];
  let i = 0;
  while (i < out.length) {
    if (!trailingComment(out[i]!)) {
      i++;
      continue;
    }
    let j = i;
    while (j < out.length && trailingComment(out[j]!)) j++;
    const block = out.slice(i, j).map((l) => trailingComment(l)!);
    const width = Math.max(...block.filter((b) => b.text !== undefined).map((b) => b.code.length), 0);
    block.forEach((b, k) => {
      if (b.text !== undefined) out[i + k] = `${b.code.padEnd(width)} // ${fix(b.text)}`;
    });
    i = j;
  }
  return out;
}

// Markdown の本文の判定単位: 段落・箇条書き・見出し・引用の行と表のセル
export function markdownTexts(source: string): { line: number; text: string }[] {
  const out: { line: number; text: string }[] = [];
  // 対象外: コードブロック（``` と ~~~・インデントされたもの）・HTML のコメント・先頭の front matter
  let fence = '';
  let comment = false;
  const lines = source.split(/\r?\n/);
  const frontMatter = lines[0] === '---' ? lines.indexOf('---', 1) : -1;
  lines.forEach((raw, i) => {
    if (i <= frontMatter) return;
    // 引用の記号（入れ子を含む）を除外してから判定
    const l = raw.replace(/^(\s*>)+\s?/, '');
    const marker = l.match(/^\s*(```|~~~)/)?.[1];
    if (marker && (!fence || fence === marker)) {
      fence = fence ? '' : marker;
      return;
    }
    if (fence || !l.trim()) return;
    if (comment || l.trimStart().startsWith('<!--')) {
      comment = !l.includes('-->');
      return;
    }
    // 見出し・箇条書き（タスクのチェックボックスを含む）の記号は除外
    const texts = l.startsWith('|') ? l.split(/(?<!\\)\|/).slice(1, -1).map((c) => c.trim()) : [l.replace(/^#+\s+|^\s*(?:[-*+]|\d+\.)\s+(?:\[[ xX]\]\s+)?/, '')];
    // リンクの URL 部分（`](...)`）と表の区切り行は判定対象外
    for (const text of texts) if (text && !/^:?-+:?$/.test(text)) out.push({ line: i + 1, text: text.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1') });
  });
  return out;
}
